package com.bank.advisory.service;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import java.util.logging.Logger;

// Finds the K quotes closest to a target in a sorted array.
public class QuoteAdvisoryService {
    private static final Logger log = Logger.getLogger(QuoteAdvisoryService.class.getName());

    public List<Integer> kClosest(int[] quotes, int target, int k) {
        int idx = binarySearchBoundary(quotes, target);
        int low = idx - 1, high = idx, n = quotes.length;
        Deque<Integer> window = new ArrayDeque<>();
        for (int count = 0; count < k; count++) {
            boolean takeLeft = low >= 0 &&
                (high >= n || target - quotes[low] <= quotes[high] - target); // tie → smaller
            if (takeLeft) window.addFirst(quotes[low--]);
            else window.addLast(quotes[high++]);
        }
        List<Integer> result = new ArrayList<>(window);
        log.info(() -> "K closest to " + target + " = " + result);
        return result;
    }

    private int binarySearchBoundary(int[] a, int target) {
        int start = 0, end = a.length - 1;
        while (start <= end) {
            int mid = start + (end - start) / 2;
            if (a[mid] == target) return mid;
            if (a[mid] < target) start = mid + 1; else end = mid - 1;
        }
        return start; // insertion point when absent
    }
}
